import{_ as n,C as o,o as d,c as r,a2 as p,j as e,E as t}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"Laravel SaaS Project Structure","description":"Folder layout of a SaaS Laravel kit: app, Modules, config, database, lang, resources/js and tests, plus how each module groups its code by layer.","frontmatter":{"title":"Laravel SaaS Project Structure","description":"Folder layout of a SaaS Laravel kit: app, Modules, config, database, lang, resources/js and tests, plus how each module groups its code by layer.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/getting-started/project-structure.html"}],["meta",{"property":"og:title","content":"Laravel SaaS Project Structure"}],["meta",{"property":"og:description","content":"Folder layout of a SaaS Laravel kit: app, Modules, config, database, lang, resources/js and tests, plus how each module groups its code by layer."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/getting-started/project-structure.html"}],["meta",{"name":"twitter:title","content":"Laravel SaaS Project Structure"}],["meta",{"name":"twitter:description","content":"Folder layout of a SaaS Laravel kit: app, Modules, config, database, lang, resources/js and tests, plus how each module groups its code by layer."}]]},"headers":[],"relativePath":"docs/getting-started/project-structure.md","filePath":"docs/getting-started/project-structure.md","lastUpdated":1790486087000}'),l={name:"docs/getting-started/project-structure.md"},c={tabindex:"0"};function i(u,a,h,m,g,v){const s=o("Badge");return d(),r("div",null,[a[2]||(a[2]=p(`<h1 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h1><h2 id="kit-layout" tabindex="-1">Kit layout <a class="header-anchor" href="#kit-layout" aria-label="Permalink to &quot;Kit layout&quot;">​</a></h2><p>A kit is a standard Laravel app with one addition: features live in <code>Modules/</code> instead of being spread across <code>app/</code>. React and Svelte have the same backend folders as Vue; only <code>resources/js</code> differs (see the framework guides: <a href="/docs/vue/architecture.html">Vue</a>, <a href="/docs/react/architecture.html">React</a>, <a href="/docs/svelte/architecture.html">Svelte</a>).</p><table tabindex="0"><thead><tr><th>Folder</th><th>What lives there</th></tr></thead><tbody><tr><td><code>app/</code></td><td>Shared infrastructure: middleware, tenancy listeners, models, providers</td></tr><tr><td><code>Modules/</code></td><td>Feature modules (<code>Auth</code>, <code>Dashboard</code>, <code>Menu</code>, <code>RolePermission</code>, <code>Settings</code>, <code>Tenant</code>, <code>User</code>)</td></tr><tr><td><code>bootstrap/</code></td><td><code>app.php</code> (middleware, aliases, error pages), <code>providers.php</code> (app and module providers)</td></tr><tr><td><code>config/</code></td><td>Laravel config plus <code>tenancy.php</code>, <code>fortify.php</code>, <code>inertia-lang.php</code> and the <code>permissions/</code> files</td></tr><tr><td><code>database/</code></td><td>Central migrations and seeders, with <code>tenant/</code> subfolders for tenant databases</td></tr><tr><td><code>lang/</code></td><td>17 locales; kit strings in <code>lang/&lt;locale&gt;/modules/</code></td></tr><tr><td><code>resources/js/</code></td><td>Inertia pages, components, layouts, generated types, translations and routes</td></tr><tr><td><code>routes/</code></td><td><code>web.php</code> is empty; routes live in modules</td></tr><tr><td><code>tests/</code></td><td>Pest feature and unit tests</td></tr><tr><td><code>.agents/</code>, <code>.claude/</code>, <code>.ai/</code>, <code>boost.json</code>, <code>AGENTS.md</code>, <code>CLAUDE.md</code></td><td>Laravel Boost AI tooling</td></tr></tbody></table><details class="details custom-block"><summary>View the full directory tree (Vue kit)</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-saas/</span></span>
<span class="line"><span>├── app/</span></span>
<span class="line"><span>│   ├── Concerns/                  # PasswordValidationRules, ProfileValidationRules</span></span>
<span class="line"><span>│   ├── Http/Middleware/           # HandleInertiaRequests, InitializeTenancyIfTenantDomain,</span></span>
<span class="line"><span>│   │                              # PreventAccessFromTenantDomains, TenancyAware* auth middleware</span></span>
<span class="line"><span>│   ├── Listeners/                 # ConfigureTenantAuth, RevertTenantAuth, ApplyTenantAppName, ...</span></span>
<span class="line"><span>│   ├── Models/                    # User, Tenant, Domain, Menu, LayoutSetting, Setting</span></span>
<span class="line"><span>│   ├── Providers/                 # AppServiceProvider, TenancyServiceProvider, TypeScriptTransformerServiceProvider</span></span>
<span class="line"><span>│   └── Support/TypeScriptTransformer/</span></span>
<span class="line"><span>├── Modules/                       # Feature modules (PSR-4 namespace Modules\\)</span></span>
<span class="line"><span>│   ├── Auth/                      # Fortify actions + views</span></span>
<span class="line"><span>│   ├── Dashboard/                 # Home page + dashboard</span></span>
<span class="line"><span>│   ├── Menu/                      # DB-driven navigation</span></span>
<span class="line"><span>│   ├── RolePermission/            # Roles, permission config loader</span></span>
<span class="line"><span>│   ├── Settings/                  # Profile, security, language, layout</span></span>
<span class="line"><span>│   ├── Tenant/                    # Tenants, domains, maintenance, invitations</span></span>
<span class="line"><span>│   └── User/                      # User management + invitations</span></span>
<span class="line"><span>├── bootstrap/</span></span>
<span class="line"><span>│   ├── app.php                    # Middleware, aliases, error page rendering</span></span>
<span class="line"><span>│   └── providers.php              # App + module service providers</span></span>
<span class="line"><span>├── config/</span></span>
<span class="line"><span>│   ├── permissions/               # Central permission files (dashboard, menus, roles, settings, tenants, users)</span></span>
<span class="line"><span>│   │   └── tenant/                # Tenant permission files</span></span>
<span class="line"><span>│   ├── tenancy.php  fortify.php  auth.php  permission.php  inertia-lang.php  queue.php ...</span></span>
<span class="line"><span>├── database/</span></span>
<span class="line"><span>│   ├── migrations/                # Central database</span></span>
<span class="line"><span>│   │   └── tenant/                # Every tenant database</span></span>
<span class="line"><span>│   ├── seeders/                   # DatabaseSeeder, RoleSeeder, PermissionSeeder, MenuSeeder, DefaultUserSeeder</span></span>
<span class="line"><span>│   │   └── tenant/                # TenantDatabaseSeeder, tenant RoleSeeder, tenant MenuSeeder</span></span>
<span class="line"><span>│   └── factories/</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>│   └── &lt;locale&gt;/                  # 17 locales</span></span>
<span class="line"><span>│       ├── auth.php  pagination.php  passwords.php  validation.php</span></span>
<span class="line"><span>│       └── modules/               # auth, common, dashboard, domain, errors, home, layout,</span></span>
<span class="line"><span>│                                  # maintenance, menu, role, security, settings, tenant, user</span></span>
<span class="line"><span>├── resources/</span></span>
<span class="line"><span>│   ├── css/app.css</span></span>
<span class="line"><span>│   ├── views/app.blade.php        # Inertia root view</span></span>
<span class="line"><span>│   └── js/</span></span>
<span class="line"><span>│       ├── app.ts                 # createInertiaApp + default layouts</span></span>
<span class="line"><span>│       ├── pages/                 # Inertia pages (auth, errors, roles, settings, setup, tenants, users)</span></span>
<span class="line"><span>│       ├── components/            # App components, common/ form components, ui/ (shadcn)</span></span>
<span class="line"><span>│       ├── layouts/               # AppLayout, AuthLayout, app/, auth/, settings/</span></span>
<span class="line"><span>│       ├── composables/           # usePermission, useLanguage, useConfirmDialog, ...</span></span>
<span class="line"><span>│       ├── lib/                   # utils, flashToast</span></span>
<span class="line"><span>│       ├── lang/&lt;locale&gt;/         # Generated by erag:generate-lang</span></span>
<span class="line"><span>│       ├── types/                 # Hand-written types + generated Modules/* types</span></span>
<span class="line"><span>│       ├── actions/  routes/  wayfinder/   # Generated by Wayfinder (git-ignored)</span></span>
<span class="line"><span>├── routes/</span></span>
<span class="line"><span>│   ├── web.php                    # Empty: routes live in modules</span></span>
<span class="line"><span>│   ├── tenant.php                 # stancl sample tenant routes</span></span>
<span class="line"><span>│   └── console.php</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│   ├── Feature/                   # Auth, Settings, Dashboard (+ Tenancy in React/Svelte)</span></span>
<span class="line"><span>│   ├── Unit/</span></span>
<span class="line"><span>│   ├── Pest.php  TestCase.php</span></span>
<span class="line"><span>├── .agents/skills  .claude/skills  .ai/rules  boost.json  AGENTS.md  CLAUDE.md   # Laravel Boost AI tooling</span></span>
<span class="line"><span>├── composer.json  package.json  vite.config.ts  phpstan.neon  pint.json  phpunit.xml</span></span></code></pre></div></details><h2 id="inside-a-module" tabindex="-1">Inside a module <a class="header-anchor" href="#inside-a-module" aria-label="Permalink to &quot;Inside a module&quot;">​</a></h2><p>Each module is self-contained: it has its own routes, controllers, Data objects, services and enums, and registers its routes from its service provider (listed in <code>bootstrap/providers.php</code>). Adding a feature usually means adding a module, not touching <code>app/</code>.</p><p><code>Modules/Tenant</code> is the most complete example:</p><table tabindex="0"><thead><tr><th>Folder</th><th>Contains</th><th>Examples</th></tr></thead><tbody><tr><td><code>Data/</code></td><td>spatie/laravel-data classes: validation (rules, attributes, messages) + TS types</td><td><code>TenantRegisterData</code>, <code>DomainData</code></td></tr><tr><td><code>Enums/</code></td><td>Option lists</td><td><code>WorkspaceStatusEnum</code>, <code>IndustryEnum</code>, <code>TeamSizeEnum</code>, <code>WorkWeekEnum</code></td></tr><tr><td><code>Http/Controllers/</code></td><td>Thin controllers: validate via Data, call a Service, render or redirect</td><td><code>TenantController</code>, <code>DomainController</code></td></tr><tr><td><code>Http/Middleware/</code></td><td>Request guards</td><td><code>EnsureTenantIsNotSuspended</code>, <code>EnsureTenantIsNotInMaintenance</code>, <code>EnsureTenantAuthFeatureEnabled</code></td></tr><tr><td><code>Http/Requests/</code></td><td>Form requests where a Data class is not used</td><td><code>AcceptInvitationRequest</code></td></tr><tr><td><code>Jobs/</code></td><td>Queueable jobs</td><td><code>CreateTenantUserJob</code></td></tr><tr><td><code>Listeners/</code></td><td>Tenancy event listeners</td><td><code>ApplyTenantFortifyFeatures</code>, <code>RestoreCentralFortifyFeatures</code></td></tr><tr><td><code>Notifications/</code></td><td>Emails</td><td><code>TenantInvitationNotification</code>, <code>TenantPasswordResetNotification</code></td></tr><tr><td><code>Providers/</code></td><td>Module service provider</td><td><code>TenantServiceProvider</code></td></tr><tr><td><code>Repositories/</code></td><td>Complex queries</td><td><code>TenantRepository</code>, <code>DomainRepository</code></td></tr><tr><td><code>Rules/</code></td><td>Validation rules</td><td><code>IpAddressOrCidr</code>, <code>UniqueTenantDomain</code></td></tr><tr><td><code>Services/</code></td><td>Business logic</td><td><code>TenantService</code>, <code>DomainService</code>, <code>TenantMaintenanceService</code>, <code>TenantAuthFeatureService</code></td></tr><tr><td><code>routes/web.php</code></td><td>Central routes</td><td>Tenants, domains, tenant settings</td></tr><tr><td><code>routes/tenant.php</code></td><td>Tenant-only routes</td><td>Invitation accept, maintenance bypass</td></tr></tbody></table><p>See <a href="/docs/core/architecture.html">Architecture</a> for how requests flow through these pieces.</p><h2 id="frontend-naming-per-kit" tabindex="-1">Frontend naming per kit <a class="header-anchor" href="#frontend-naming-per-kit" aria-label="Permalink to &quot;Frontend naming per kit&quot;">​</a></h2>`,11)),e("table",c,[e("thead",null,[e("tr",null,[a[0]||(a[0]=e("th",null,null,-1)),e("th",null,[t(s,{type:"tip",text:"Vue"})]),e("th",null,[t(s,{type:"tip",text:"React"})]),e("th",null,[t(s,{type:"tip",text:"Svelte"})])])]),a[1]||(a[1]=e("tbody",null,[e("tr",null,[e("td",null,"Pages"),e("td",null,[e("code",null,"pages/tenants/Index.vue")]),e("td",null,[e("code",null,"pages/tenants/index.tsx")]),e("td",null,[e("code",null,"pages/tenants/Index.svelte")])]),e("tr",null,[e("td",null,"Shared logic"),e("td",null,[e("code",null,"composables/usePermission.ts")]),e("td",null,[e("code",null,"hooks/use-permission.ts")]),e("td",null,[e("code",null,"lib/permission.ts")])]),e("tr",null,[e("td",null,"Type check"),e("td",null,[e("code",null,"vue-tsc")]),e("td",null,[e("code",null,"tsc")]),e("td",null,[e("code",null,"svelte-check")])])],-1))])])}const b=n(l,[["render",i]]);export{f as __pageData,b as default};
